$(window).on("scroll",function(){60<$(this).scrollTop()?$("header").addClass("active"):$("header").removeClass("active")}),jQuery(document).ready(function(e){e("#slider-topo").slick({autoplay:!1,arrows:!1,dots:!0,speed:500,fade:!0,cssEase:"linear"}),e("#slider-depoimentos").slick({autoplay:!1,slidesToShow:2,slidesToScroll:1,infinite:!0,arrows:!1,dots:!0,speed:500})});